from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import dijkstra
h,w=img.shape
coords=np.argwhere(img>0); idx=np.full((h,w),-1,np.int32);idx[img>0]=np.arange(len(coords))
rr=[];cc=[];dd=[]
for a,(y,x) in enumerate(coords):
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not(dx or dy):continue
   yy,xx=y+dy,x+dx
   if 0<=yy<h and 0<=xx<w and idx[yy,xx]>=0:
    rr.append(a);cc.append(idx[yy,xx]);dd.append((dx*dx+dy*dy)**.5)
g=coo_matrix((dd,(rr,cc)),shape=(len(coords),len(coords))).tocsr()
def findpt(pt):
 x,y=pt; j=np.argmin(np.sum((coords[:,::-1]-pt)**2,axis=1));return j

def path(a,b):
 ds,pr=dijkstra(g,indices=findpt(a),return_predecessors=True); j=findpt(b); out=[]
 while j!=-9999 and j!=-1:
  out.append(coords[j][::-1]);
  if j==findpt(a):break
  j=pr[j]
 return np.array(out[::-1])
def sparse(p,step=15):
 lens=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))]; s=np.arange(0,lens[-1],step); out=[]
 for z in s:
  j=np.searchsorted(lens,z)-1;j=max(0,min(j,len(p)-2)); t=(z-lens[j])/(lens[j+1]-lens[j]+1e-9);out.append(p[j]*(1-t)+p[j+1]*t)
 out.append(p[-1]);return [(round(a),round(b)) for a,b in out]
for a,b in [((343,322),(536,348)),((343,322),(464,619)),((415,472),(464,619)),((287,452),(322,487)),((287,452),(297,759)),((322,487),(297,759))]:
 p=path(a,b); print(a,'->',b,'len',len(p),'arc',np.sum(np.linalg.norm(np.diff(p,axis=0),axis=1)),'pts',sparse(p,20))
