import numpy as np,cv2
from PIL import Image
D=np.load('/tmp/parts.npz'); P=[D[k].astype(bool) for k in sorted(D.files,key=lambda x:int(x.split('_')[1]))]
T=np.array(Image.open('/app/target.png').convert('RGB')).mean(2)<128
K=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(3,3)); tol=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(9,9))
te=T&~cv2.erode(T.astype('uint8'),K).astype(bool); td=cv2.dilate(te.astype('uint8'),tol).astype(bool); dist=cv2.distanceTransform((~T).astype('uint8'),cv2.DIST_L2,5)
def shift(m,dx,dy):
 o=np.zeros_like(m); ys=slice(max(0,dy),min(1024,1024+dy)); xs=slice(max(0,dx),min(1024,1024+dx)); o[ys,xs]=m[max(0,-dy):min(1024,1024-dy),max(0,-dx):min(1024,1024-dx)];return o
def metrics(Q):
 A=np.logical_or.reduce(Q); ae=A&~cv2.erode(A.astype('uint8'),K).astype(bool); ad=cv2.dilate(ae.astype('uint8'),tol).astype(bool)
 bp=(ae&td).sum()/ae.sum(); br=(te&ad).sum()/te.sum(); F=2*bp*br/(bp+br)
 stray=(A&(dist>4.5)).sum()/T.sum(); iou=(A&T).sum()/(A|T).sum();
 # each connected component coverage
 n,l,st,c=cv2.connectedComponentsWithStats(T.astype('uint8'),8)
 cov=[(l==i).__and__(A).sum()/st[i,cv2.CC_STAT_AREA] for i in range(1,n)]
 return F,stray,iou,min(cov)
S=[(0,0)]*len(P)
def build(): return [shift(P[i],*S[i]) for i in range(len(P))]
print('base',metrics(build()))
# score tradeoffs and coordinate descent
for penalty in [2,5,10,20]:
 S=[(0,0)]*len(P)
 for it in range(2):
  for i in range(len(P)):
   best=None
   for dy in range(-7,8):
    for dx in range(-7,8):
     SS=S.copy(); SS[i]=(dx,dy); m=metrics([shift(P[j],*SS[j]) for j in range(len(P))]); obj=m[0]+.2*m[2]-penalty*max(0,m[1]-.039)
     if best is None or obj>best[0]:best=(obj,dx,dy,m)
   S[i]=(best[1],best[2]);print(penalty,it,i,S[i],best[3],best[0])
 print('FINAL',penalty,S,metrics(build()))
